export default function HomeScreen() {
  const theme = useTheme();
  const { data, error, isError, isFetching, failureCount, refetch } = useBalances();
  const [pulling, setPulling] = useState(false);

  if (!data) {
    if (isError) {
      return <ErrorView error={error} onRetry={() => refetch()} retrying={isFetching} />;
    }
    return (
      <LoadingView
        label="Loading balances…"
        hint={failureCount > 0 ? 'The server is slow to respond. Retrying…' : undefined}
      />
