      style={({ pressed }) => [styles.headerButton, pressed && styles.pressed]}>
      <ThemedText type="smallBold" themeColor="tint">
        Token
      </ThemedText>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  headerButton: {
    paddingHorizontal: Spacing.three,
    paddingVertical: Spacing.two,
  },
  pressed: {
    opacity: 0.6,
  },
});

