/**
 * Exact money math.
 *
 * Asset amounts are kept as bigint counts of the asset's smallest unit
 * (e.g. "820.413207" USDT with 6 decimals -> 820413207n), so they never pass
 * through floating point. Prices and USD values use `Decimal` (value / 10^scale),
 * and are rounded only once, when formatted for display.
 */

export type Decimal = { value: bigint; scale: number };

export type ParseAmountResult =
  | { ok: true; units: bigint }
  | { ok: false; reason: 'format' | 'too-many-decimals' };

// API format: digits, optional dot followed by digits, no leading zeros.
// "0.5" and "12" are valid; ".5", "1.", "05", "1e-3", "-1" are not.
const DECIMAL_RE = /^(0|[1-9]\d*)(?:\.(\d+))?$/;

const pow10 = (n: number) => 10n ** BigInt(n);

export function parseDecimal(input: string): Decimal | null {
  const match = DECIMAL_RE.exec(input);
  if (!match) return null;
  const fraction = match[2] ?? '';
  return { value: BigInt(match[1] + fraction), scale: fraction.length };
}

/** Parses an asset amount, allowing at most `decimals` fraction digits (same rule as the API). */
export function parseAmount(input: string, decimals: number): ParseAmountResult {
  const parsed = parseDecimal(input);
  if (!parsed) return { ok: false, reason: 'format' };
  if (parsed.scale > decimals) return { ok: false, reason: 'too-many-decimals' };
  return { ok: true, units: parsed.value * pow10(decimals - parsed.scale) };
}

/** Canonical API string: "820.413207", "12", "0.5" (no trailing zeros, no grouping). */
export function toAmountString(units: bigint, decimals: number): string {
  const sign = units < 0n ? '-' : '';
  const abs = units < 0n ? -units : units;
  const base = pow10(decimals);
  const integer = (abs / base).toString();
  const fraction = (abs % base).toString().padStart(decimals, '0').replace(/0+$/, '');
  return sign + integer + (fraction ? '.' + fraction : '');
}

/** Display string with thousands separators. Never rounds: every unit is shown. */
export function formatAmount(units: bigint, decimals: number): string {
  const [integer, fraction] = toAmountString(units, decimals).split('.');
  return groupThousands(integer) + (fraction ? '.' + fraction : '');
}

/** Display form of an already validated decimal string from the API ("1234.5" -> "1,234.5"). */
export function formatDecimalString(input: string): string {
  const parsed = parseDecimal(input);
  return parsed ? formatAmount(parsed.value, parsed.scale) : input;
}

export function usdValue(units: bigint, decimals: number, usdPrice: Decimal): Decimal {
  return { value: units * usdPrice.value, scale: decimals + usdPrice.scale };
}

export function addDecimals(a: Decimal, b: Decimal): Decimal {
  const scale = Math.max(a.scale, b.scale);
  return {
    value: a.value * pow10(scale - a.scale) + b.value * pow10(scale - b.scale),
    scale,
  };
}

export function sumDecimals(values: Decimal[]): Decimal {
  return values.reduce(addDecimals, { value: 0n, scale: 0 });
}

export function compareDecimals(a: Decimal, b: Decimal): number {
  const diff = addDecimals(a, { value: -b.value, scale: b.scale }).value;
  return diff === 0n ? 0 : diff > 0n ? 1 : -1;
}

/** Rounds half away from zero to `scale` digits; returns the integer count of 10^-scale units. */
export function roundDecimal(d: Decimal, scale: number): bigint {
  if (d.scale <= scale) return d.value * pow10(scale - d.scale);
  const divisor = pow10(d.scale - scale);
  const abs = d.value < 0n ? -d.value : d.value;
  const rounded = (abs + divisor / 2n) / divisor;
  return d.value < 0n ? -rounded : rounded;
}

/** "$1,234.56". A non-zero value that rounds to 0 cents shows as "<$0.01". */
export function formatUsd(d: Decimal): string {
  const cents = roundDecimal(d, 2);
  if (cents === 0n && d.value > 0n) return '<$0.01';
  const sign = cents < 0n ? '-' : '';
  const abs = cents < 0n ? -cents : cents;
  const fraction = (abs % 100n).toString().padStart(2, '0');
  return `${sign}$${groupThousands((abs / 100n).toString())}.${fraction}`;
}

function groupThousands(integer: string): string {
  return integer.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

import {
  compareDecimals,
  formatAmount,
  formatDecimalString,
  formatUsd,
  parseAmount,
  parseDecimal,
  roundDecimal,
  sumDecimals,
  toAmountString,
  usdValue,
  type Decimal,
} from '../amount';

const dec = (input: string): Decimal => parseDecimal(input)!;

describe('parseAmount', () => {
  it.each<[string, number, bigint]>([
    ['0', 6, 0n],
    ['12', 6, 12_000_000n],
    ['0.5', 6, 500_000n],
    ['820.413207', 6, 820_413_207n],
    ['0.000001', 6, 1n],
    ['5', 0, 5n],
  ])('parses %p with %i decimals', (input, decimals, units) => {
    expect(parseAmount(input, decimals)).toEqual({ ok: true, units });
  });

  it('keeps precision that floating point would lose', () => {
    expect(parseAmount('123456789.123456789012345678', 18)).toEqual({
      ok: true,
      units: 123456789123456789012345678n,
    });
  });

  it.each(['', '.5', '1.', '05', '00.1', '1e-3', '-1', '+1', ' 1', '1,5', '1.2.3', 'abc'])(
    'rejects %p (not the API format)',
    (input) => {
      expect(parseAmount(input, 6)).toEqual({ ok: false, reason: 'format' });
    },
  );

  it('rejects more decimals than the asset allows, trailing zeros included', () => {
    expect(parseAmount('0.0000001', 6)).toEqual({ ok: false, reason: 'too-many-decimals' });
    expect(parseAmount('1.0000000', 6)).toEqual({ ok: false, reason: 'too-many-decimals' });
    expect(parseAmount('1.0', 0)).toEqual({ ok: false, reason: 'too-many-decimals' });
  });
});

describe('toAmountString and formatAmount', () => {
  it('writes the canonical API string without trailing zeros', () => {
    expect(toAmountString(50_120_000n, 6)).toBe('50.12');
    expect(toAmountString(12_000_000n, 6)).toBe('12');
    expect(toAmountString(1n, 6)).toBe('0.000001');
    expect(toAmountString(0n, 6)).toBe('0');
    expect(toAmountString(7n, 0)).toBe('7');
    expect(toAmountString(-1_500_000n, 6)).toBe('-1.5');
  });

  it('round-trips through parseAmount', () => {
    for (const units of [0n, 1n, 999_999n, 1_000_000n, 820_413_207n]) {
      expect(parseAmount(toAmountString(units, 6), 6)).toEqual({ ok: true, units });
    }
  });

  it('groups thousands and never rounds', () => {
    expect(formatAmount(1_234_567_891_234n, 6)).toBe('1,234,567.891234');
    expect(formatAmount(999_999_999n, 9)).toBe('0.999999999');
    expect(formatAmount(123n, 0)).toBe('123');
    expect(formatAmount(-1_234_500_000n, 6)).toBe('-1,234.5');
    expect(formatDecimalString('1234.5')).toBe('1,234.5');
  });
});

describe('USD values', () => {
  it('multiplies amount by price exactly', () => {
    // 820.413207 USDT × 1.0002 = 820.5772896414
    const value = usdValue(820_413_207n, 6, dec('1.0002'));
    expect(value).toEqual({ value: 8205772896414n, scale: 10 });
    expect(formatUsd(value)).toBe('$820.58');
  });

  it('has no floating point drift (0.1 + 0.2)', () => {
    const sum = sumDecimals([dec('0.1'), dec('0.2')]);
    expect(compareDecimals(sum, dec('0.3'))).toBe(0);
    expect(formatUsd(sum)).toBe('$0.30');
  });

  it('rounds once after summing, not per item', () => {
    // Three assets worth $0.005 each: $0.015 in total -> $0.02.
    // Rounding each first would show $0.03.
    const each = dec('0.005');
    expect(formatUsd(sumDecimals([each, each, each]))).toBe('$0.02');
  });

  it('rounds half away from zero', () => {
    expect(roundDecimal(dec('0.005'), 2)).toBe(1n);
    expect(roundDecimal(dec('0.004999'), 2)).toBe(0n);
    expect(roundDecimal({ value: -5n, scale: 3 }, 2)).toBe(-1n);
    expect(roundDecimal(dec('7'), 2)).toBe(700n);
  });

  it('formats cents, grouping and values below one cent', () => {
    expect(formatUsd(dec('1234567.89'))).toBe('$1,234,567.89');
    expect(formatUsd(dec('0'))).toBe('$0.00');
    expect(formatUsd(dec('0.00000001'))).toBe('<$0.01');
  });

  it('compares decimals with different scales', () => {
    expect(compareDecimals(dec('1.5'), dec('1.50'))).toBe(0);
    expect(compareDecimals(dec('2'), dec('1.999'))).toBe(1);
    expect(compareDecimals(dec('0.1'), dec('0.25'))).toBe(-1);
  });
});

