import { useRouter } from 'expo-router';
import { Pressable, StyleSheet, View } from 'react-native';

import type { ActivityItem } from '@/api/activity';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Spacing, type ThemeColor } from '@/constants/theme';
import { formatDecimalString } from '@/lib/amount';
import { formatDateTime } from '@/lib/time';

function title(item: ActivityItem) {
  const exchange = item.exchange ?? 'exchange';
  switch (item.type) {
    case 'accrual':
      return `Payback from ${exchange}`;
    case 'reversal':
      return `Reversed by ${exchange}`;
    case 'claim':
      return 'Claim';
  }
}

function statusLabel(item: ActivityItem): { text: string; color: ThemeColor } {
  if (item.type === 'claim') {
    if (item.status === 'completed') return { text: 'Completed', color: 'success' };
    if (item.status === 'failed') return { text: 'Failed · returned', color: 'danger' };
    return { text: 'Processing', color: 'warning' };
  }
  if (item.status === 'pending') return { text: 'Pending', color: 'warning' };
  return { text: 'Confirmed', color: 'textSecondary' };
}

/** One history entry. Claims we created link to their status screen. */
export function ActivityRow({ item }: { item: ActivityItem }) {
  const router = useRouter();
  const negative = item.amount.startsWith('-');
  const amount = `${negative ? '−' : '+'}${formatDecimalString(negative ? item.amount.slice(1) : item.amount)} ${item.asset}`;
  const status = statusLabel(item);
  // A failed claim never left the balance, and a pending accrual isn't confirmed yet.
  const settledAmount = !(item.type === 'claim' && item.status === 'failed');
  const amountColor: ThemeColor =
    item.status === 'pending' ? 'textSecondary' : negative ? 'text' : 'success';

  const content = (
    <ThemedView type="backgroundElement" style={styles.row}>
      <View style={styles.main}>
        <ThemedText type="small">{title(item)}</ThemedText>
        <ThemedText type="small" themeColor="textSecondary">
          {formatDateTime(Date.parse(item.createdAt))}
        </ThemedText>
      </View>
      <View style={styles.side}>
        <ThemedText
          type="smallBold"
          themeColor={settledAmount ? amountColor : 'textSecondary'}
          style={[styles.number, !settledAmount && styles.struck]}>
          {amount}
        </ThemedText>
        <ThemedText type="small" themeColor={status.color}>
          {status.text}
        </ThemedText>
      </View>
    </ThemedView>
  );

  const claimId = item.type === 'claim' ? item.relatedId : null;
  if (!claimId) return content;
  return (
    <Pressable
      accessibilityRole="button"
      onPress={() => router.push({ pathname: '/claims/[id]', params: { id: claimId } })}
      style={({ pressed }) => pressed && styles.pressed}>
      {content}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
